# Hypothesis: each cell slides down-left diagonally until resting (below blocked or left blocked), processing order matters.
def slide_diag(gin, mode='down-then-left'):
    g=[r[:] for r in gin]; H,W=len(g),len(g[0])
    cells=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v!=0]
    # remove duplicates then settle
    pos=set(cells)
    while True:
        moved=False
        for i,j in list(pos):
            if mode=='DL':
                if i+1<H and (i+1,j) not in pos:
                    pos.discard((i,j)); pos.add((i+1,j)); moved=True
                elif i+1>=H or (i+1,j) in pos:
                    if j>0 and (i,j-1) not in pos:
                        pos.discard((i,j)); pos.add((i,j-1)); moved=True
                    else: break
            elif mode=='L':
                if j>0 and (i,j-1) not in pos:
                    pos.discard((i,j)); pos.add((i,j-1)); moved=True
        if not moved: break
    res=[[0]*W for _ in g]
    for i,j in pos: res[i][j]=gin[i][j]
    return res
